import unittest

from text_utils import slugify


class SlugifyTests(unittest.TestCase):
    def test_words_and_punctuation(self) -> None:
        self.assertEqual(slugify("Hello, World!"), "hello-world")

    def test_collapses_separators(self) -> None:
        self.assertEqual(slugify("  Multiple___spaces  "), "multiple-spaces")

    def test_transliterates_accents(self) -> None:
        self.assertEqual(slugify("Café Déjà Vu"), "cafe-deja-vu")

    def test_empty_slug(self) -> None:
        self.assertEqual(slugify("---"), "")


if __name__ == "__main__":
    unittest.main()
